from collections import defaultdict

def get_bbox(component):
    """Get bounding box of a component"""
    rows = [r for r, c in component]
    cols = [c for r, c in component]
    return min(rows), max(rows) + 1, min(cols), max(cols)

# Get bounding boxes for each region
def find_regions_with_bbox(grid):
    h, w = len(grid), len(grid[0])
    background = 0
    visited = set()
    regions = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in visited:
                continue

            # Find connected component
            component = []
            queue = [[r, c], 1]
            visited.add((r, c))

            while queue:
                pos = queue.pop(0) if not isinstance(pos[0], list) else pos[0]
                component.append(pos[0])
                if len(pos) > 1:
                    queue.append(pos[1])

            for i, (cr, cc) in enumerate(component):
                for neighbor in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = cr + neighbor[0], cc + neighbor[1]
                    if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in visited:
                        if grid[nr][nc] == grid[cr][cc]:
                            visited.add((nr, nc))
                            queue.append([nr, nc, 0])

            regions.append((component, grid[component[0][0]][component[0][1]]))

    return regions

